import './index.less';

class StoriesRecruitButton {
  constructor({ el }) {
    this.button = document.querySelector(el);
    this.popup = document.querySelector('.stories-main-pop');
    this.mbCloseIcon = this.button.querySelector('.mb-close-icon');

    if (!this.button || !this.popup) return;

    this.initEvents();
  }

  openPopup() {
    this.popup.style.display = 'block';
    document.body.style.overflow = 'hidden';
  }

  closePopup() {
    this.popup.style.display = 'none';
    document.body.style.overflow = '';
  }

  initEvents() {
    // 点击主按钮打开弹窗
    this.button.addEventListener('click', (e) => {
      // 如果点击的是关闭按钮，不打开弹窗
      if (e.target.closest('.mb-close-icon')) return;
      this.openPopup();
    });

    // 点击遮罩或关闭图标关闭弹窗
    this.popup.addEventListener('click', (e) => {
      // 检查是否点击了关闭图标
      if (e.target.closest('.pop-close-icon')) {
        this.closePopup();
      }
    });

    // 键盘 ESC 关闭弹窗
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        this.closePopup();
      }
    });

    // 点击关闭按钮隐藏整个按钮区域
    if (this.mbCloseIcon) {
      this.mbCloseIcon.addEventListener('click', (e) => {
        e.stopPropagation();
        this.button.style.display = 'none';
      });
    }
  }
}

document.addEventListener('DOMContentLoaded', () => {
  new StoriesRecruitButton({ el: '.stories-button' });
});
